import{z as s,x as d,o as E,c as B,q as l,j as r,D as e,d as t,s as A,S as i,b as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"长视频理解","description":"","frontmatter":{"title":"长视频理解","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/long-video-understanding.md","filePath":"llm/long-video-understanding.md","lastUpdated":1791413859000}'),p={name:"llm/long-video-understanding.md"};function m(h,a,C,c,f,D){const n=d("Mermaid");return E(),B("div",null,[a[2]||(a[2]=l('<h1 id="长视频理解" tabindex="-1">长视频理解 <a class="header-anchor" href="#长视频理解" aria-label="Permalink to &quot;长视频理解&quot;">​</a></h1><div class="epigraph"><p>小时级视频的问题不是「再多几张图」，而是哪些帧进上下文、记忆里留什么、问的是哪一秒。</p><footer>—— 对照 Video-LLaVA / Video-ChatGPT 的短视频对话；MovieChat、LongVA 的长上下文与记忆</footer></div><p><a href="/llm/chart-table-understanding">上一课</a>在单张结构画布上读数。主干<a href="/llm/video-tokens">视频 token</a> 已写抽帧与时间位置。本课缺口是长：超出现场窗口的叙事、重复镜头、要检索的事件。后课多模态推理默认你已经能指向「哪一段」，再谈用看见的当证据。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>短视频 VLM 把 \\(T\\) 帧各编成 \\(N\\) 个 patch，序列是 \\(TN\\)，再加文本。分钟以上会先打爆窗口，相邻帧还高度冗余。均匀低帧率会丢掉闪光与口型；只留关键帧又会丢掉连续动作。问「开头穿什么、结尾有没有同一只包」需要跨段比较，不是当前几秒的 caption。</p><p><span class="marginnote">数字实例：一小时视频按每秒 1 帧抽，是 3600 帧；每帧编成 576 个 token，就是约 200 万个视觉 token，超出 128k 窗口十几倍。所以长视频的第一道坎不是模型不聪明，而是原始帧根本放不进上下文，必须先做取舍。</span></p><p>MovieChat 把短时记忆与长时记忆分开：近段高分辨率，远处摘要。LongVA 一类把长上下文能力迁到视觉帧序列。没有记忆层次时，所谓长视频只是截断后的短视频。</p><p><span class="marginnote">时间位置必须对齐绝对时间，见视频 token 课。只按「第几张输入帧」编号，2 fps 与 10 fps 下同一物理事件对不上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三件套：采样策略（均匀 / 动态 FPS / 场景切）；记忆（滑窗、摘要 token、检索过去帧）；提问接口（时间戳、第几分钟）。视觉前端仍是 <a href="/llm/vit-as-encoder">ViT</a> + <a href="/llm/llava-projector">投影器</a>，只是 \\(T\\) 与压缩改变 \\(N_{\\mathrm{total}}\\)。评测要含长时针（事件顺序、跨段指代），不要只用短剪辑 VQA。与生成式视频模型分开：本课是理解，不采样像素。</p><p><span class="marginnote">术语翻译：「动态 FPS 抽帧」就是按画面变化快慢决定每秒取几帧——静止的空镜一分钟只取几帧，打斗或口型特写一秒多取几帧。比起均匀抽帧，它在同样 token 预算下把预算花在信息密集的秒上。</span></p>',11)),(E(),r(i,null,{default:e(()=>[A(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20VID%5B%22%E9%95%BF%E8%A7%86%E9%A2%91%22%5D%20--%3E%20SMP%5B%22%E6%8A%BD%E5%B8%A7%20%2F%20%E5%9C%BA%E6%99%AF%22%5D%0A%20%20SMP%20--%3E%20MEM%5B%22%E7%9F%AD%E6%97%B6%E4%B8%8E%E9%95%BF%E6%97%B6%E8%AE%B0%E5%BF%86%22%5D%0A%20%20MEM%20--%3E%20LLM%5B%22%E5%B8%A6%E6%97%B6%E9%97%B4%E4%BD%8D%E7%BD%AE%E7%9A%84%20LLM%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[t("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"注意力只在当前窗口内混合。长程依赖要么靠把关键帧留在窗口里，要么靠记忆写出的摘要 token——摘要一旦丢掉物体，后面的指代只能靠语言先验，幻觉会回来。因此长视频理解的上限经常是记忆写什么，不是再加一层投影。",-1)),(E(),r(i,null,{default:e(()=>[A(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E9%A2%98%EF%BC%9A%E5%BC%80%E5%A4%B4%E9%82%A3%E5%8F%AA%E5%8C%85%E5%90%8E%E6%9D%A5%E5%87%BA%E7%8E%B0%E8%BF%87%E5%90%97%3F%22%5D%20--%3E%20ATT%5B%22%E7%AA%97%E5%8F%A3%E5%86%85%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20ATT%20--%3E%7C%22%E8%BF%91%E6%AE%B5%22%7C%20S%5B%22%E7%9F%AD%E6%97%B6%E8%AE%B0%E5%BF%86%EF%BC%9A%E9%AB%98%E5%88%86%E8%BE%A8%E7%8E%87%E8%BF%91%E5%B8%A7%22%5D%0A%20%20ATT%20--%3E%7C%22%E8%BF%9C%E5%A4%84%22%7C%20L%5B%22%E9%95%BF%E6%97%B6%E8%AE%B0%E5%BF%86%EF%BC%9A%E6%91%98%E8%A6%81%20token%22%5D%0A%20%20L%20--%3E%7C%22%E6%91%98%E8%A6%81%E5%86%99%E5%85%A5%E4%BA%86%E7%89%A9%E4%BD%93%22%7C%20OK%5B%22%E6%A3%80%E7%B4%A2%E5%9B%9E%E8%AF%A5%E5%B8%A7%E5%B9%B6%E5%9B%9E%E7%AD%94%22%5D%0A%20%20L%20--%3E%7C%22%E6%91%98%E8%A6%81%E4%B8%A2%E4%BA%86%E7%89%A9%E4%BD%93%22%7C%20HALL%5B%22%E5%8F%AA%E5%89%A9%E8%AF%AD%E8%A8%80%E5%85%88%E9%AA%8C%EF%BC%8C%E5%BC%80%E5%A7%8B%E7%BC%96%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">常见误区：初学者容易以为长视频能力靠换更大的投影器或塞更多帧，实际上瓶颈常在记忆写了什么。摘要里没记「红色手提包」，后面问包去哪了，模型只能按常识编一个，视觉证据链在摘要那一步就断了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>窗口与记忆都有损。下一课在「已经看见」的前提下做多步推理，而不是再加帧。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长视频是采样 + 记忆 + 时间协议，不是多图拼接。</li><li>摘要会丢物体，跨段指代会退回语言先验。</li><li>评测必须含跨段事件，不只短剪辑 caption。</li><li>出处：Video-LLaVA、Video-ChatGPT；MovieChat；LongVA。</li></ul>',5))])}const F=s(p,[["render",m]]);export{u as __pageData,F as default};
